const vehicle = { wheels: 4, fuel: "petrol" };
const taxi = Object.create(vehicle);
taxi.fuel = "electric";
const cab = Object.create(taxi);
cab.driver = "Kim";

console.log(cab.driver, cab.fuel, cab.wheels);
console.log(cab.plate);
console.log(Object.getPrototypeOf(cab) === vehicle);
console.log(Object.getPrototypeOf(Object.getPrototypeOf(cab)) === vehicle);
